int main() // LLVM ORC REPL
{
    test_main();

    // yydebug = 1;

    std::cout
        << "========================================\n"
        << "LLVM Compiler REPL\n"
        << "========================================\n"
        << "Type an expression and press Enter.\n"
        << "Type 'e' to quit.\n\n";

    std::string line;

    while (true)
    {
        std::cout << "> ";

        if (!std::getline(std::cin, line))
            break;

        if (line == "e")
            break;

        if (line.empty())
            continue;

        /*
         * Flex normally reads from stdin.
         *
         * For the REPL we create a temporary stream
         * containing exactly one line of source code.
         */
        std::string input = line + "\n";

        FILE *inputFile = tmpfile();

        if (!inputFile)
        {
            std::cerr
                << "Error: could not create input buffer.\n";

            continue;
        }

        fwrite(
            input.c_str(),
            1,
            input.size(),
            inputFile);

        rewind(inputFile);

        yyin = inputFile;

        parsedProgram.reset();

        int result = yyparse();

        fclose(inputFile);

        if (result != 0)
        {
            std::cerr
                << "Parsing failed.\n";

            continue;
        }

        if (parsedProgram)
        {
            std::cout
                << "\n=== AST ===\n";

            parsedProgram->print();
            
            // we need to take the ast and do type checking
            TypeChecker typeChecker = TypeChecker();
            typeChecker.do_type_checking(parsedProgram);
            
            // and then do IR code generation
            generate_IR_code(std::move(parsedProgram));

            // and then compile to machine code and run it.

            std::cout
                << "============\n\n";
        }
    }

    std::cout
        << "\nApplication Terminated!\n";

    return 0;
}

